def argmax_last(xs):
    best = None
    for i, x in enumerate(xs):
        if best is None or x >= xs[best]:
            best = i
    return best

def runner_up_gap(xs):
    levels = sorted(set(xs), reverse=True)
    if len(levels) < 2:
        return None
    return levels[0] - levels[1]

def merge_ticks(a, b):
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        ta, pa = a[i]
        tb, pb = b[j]
        if ta == tb:
            out.append((ta, (pa + pb) / 2))
            i += 1
            j += 1
        elif ta < tb:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    return out + a[i:] + b[j:]

def round_trips(trades):
    pos, count = 0, 0
    for t in trades:
        new = pos + t
        if new == 0 and pos != 0:
            count += 1
        pos = new
    return count

def busiest_symbols(trades, k):
    totals = {}
    for sym, qty in trades:
        totals[sym] = totals.get(sym, 0) + abs(qty)
    order = sorted(totals, key=lambda s: -totals[s])
    return order[:k]

def nonneg_walk_counts(n):
    counts = {0: 1}
    for _ in range(n):
        nxt = {}
        for pos, ways in counts.items():
            for step in (1, -1):
                new = pos + step
                if new >= 0:
                    nxt[new] = nxt.get(new, 0) + ways
        counts = nxt
    return counts

